23: /** Movimiento tipo Fisher-Yates: ordena el array en su lugar, uniformemente al azar. */
24: function mezclar<T>(items: T[]): T[] {
25:   for (let i = items.length - 1; i > 0; i--) {
26:     const j = Math.floor(Math.random() * (i + 1));
27:     [items[i], items[j]] = [items[j], items[i]];
28:   }
29:   return items;
30: }
31: 
32: /**
33:  * Sortea las asignaciones.
34:  *
35:  * Se mezcla aleatoriamente la lista de "receptores"; si la mezcla deja a
36:  * alguien emparejado consigo mismo (punto fijo), se re-mezcla completa.
37:  * Con 2 participantes la única posibilidad válida es que intercambien.
38:  * Devuelve null si no es posible (menos de 2 participantes).
39:  */
40: export function sortearAmigoSecreto(participantes: Participante[]): Asignacion[] | null {
41:   if (participantes.length < 2) {
42:     return null;
43:   }
44: 
45:   const maxIntentos = 1000;
46:   for (let intento = 0; intento < maxIntentos; intento++) {
47:     const receptores = mezclar([...participantes]);
48:     const hayPuntoFijo = participantes.some((p, i) => p === receptores[i]);
49:     if (hayPuntoFijo) continue;
50: 
51:     return participantes.map((de, i) => ({ de, para: receptores[i] }));
52:   }
53: 
54:   // Prácticamente inalcanzable: la probabilidad de fallar 1000 intentos es baja,
55:   // pero la caída ordenada (rotación circular) siempre es un derangement válido.
56:   const rotados = participantes.slice(1).concat(participantes[0]);
57:   return participantes.map((de, i) => ({ de, para: rotados[i] }));
58: }

