```ts
export function sortearAsignaciones(participantes, { exclusiones, cantidadAmigos }) {
  const n = participantes.length;
  if (n < 2 || cantidadAmigos < 1 || cantidadAmigos > n - 1) return null;

  // matriz de bloqueo
  const bloqueado: boolean[][] = ...; // bloqueado[i][j] = i no puede dar a j
  for i: bloqueado[i][i] = true
  for ([a,b] of exclusiones) { bloqueado[a][b] = bloqueado[b][a] = true; }

  // verificación temprana: cada donner necesita k receptores disponibles
  for each i: count disponibles >= k, else return null

  const maxIntentos = 500;
  for attempts:
    const intento = resolver(n, k, bloqueado);
    if (intento) return a Asignaciones;
  return null;
}

function resolver(n, k, bloqueado): number[][] | null {
  // capacidadRestante[j]
  const capacidad = new Array(n).fill(k);
  const pendientePorDar = new Array(n).fill(k);
  const asignado: number[][] = n x [];

  slots total = n*k. loop over total slots:
    // elegir el donner no terminado con menos opciones (MCV)
    let mejor = -1, mejorOpciones = Infinity, mejorLista
    for i in shuffled order? for determinism of tie-breaking, precompute random order:
      if pendientePorDar[i] === 0 continue
      lista = receptores j con capacidad[j]>0 && !bloqueado[i][j]
      si lista.length < pendientePorDar[i] → return null (imposible en este camino)
      si lista.length < mejorOpciones { mejor=i; mejorLista=lista }
    // asignar un receptor al azar de mejorLista? Pero mejor donner tiene múltiples slots pendientes; asignar solo uno:
    j = aleatorio de mejorLista (quizá ponderado hacia receptores con más capacidad restante relativa... simple: random)
    asignado[mejor].push(j); capacidad[j]--; pendientePorDar[mejor]--
```

One slot per iteration, recomputing MCV each time: O(n*k*slots) = O(n^2*k^2), fine for n≤100.

Additionally, a smarter tie-break: prefer receivers with highest remaining capacity proportionally? To avoid starving receivers... capacity is symmetric (all must reach exactly k at end). Biased pick toward low capacity can bottleneck others. Random pick is fine with restarts.

Also handle exclusion feasibility quickly (early return) — done above.

Then map indices → Asignacion. For k=1, returns Asignacion[] of n items (same shape as before).

Ordering of returned assignments: one per giver.

