function intentarSorteo(n, k, bloqueado): number[][] | null {
  const asignados: number[][] = Array.from({length: n}, () => []);
  const capacidad = new Array(n).fill(k);
  const pendiente = new Array(n).fill(k);
  const totalSlots = n * k;

  for (let slot = 0; slot < totalSlots; slot++) {
    // Elegir el donante pendiente con menos opciones (participante más restringido)
    let mejorDonante = -1;
