const net = require("net");
const fs = require("fs");
const ARCHIVO = "/tmp/opencode/sorteo-test/correos.txt";

let mensajes = [];

net.createServer((sock) => {
  sock.write("220 test ESMTP\r\n");
  let buffer = "";
  let enData = false;
  let data = [];
  let remitente = "";
  let destinatarios = [];

  sock.on("data", (d) => {
    buffer += d.toString();
    while (buffer.includes("\r\n")) {
      const line = buffer.slice(0, buffer.indexOf("\r\n"));
      buffer = buffer.slice(buffer.indexOf("\r\n") + 2);
      if (enData) {
        if (line === ".") {
          mensajes.push({ remitente, destinatarios: [...destinatarios], data: data.join("\r\n") });
          data = []; destinatarios = []; remitente = "";
          enData = false;
          sock.write("250 OK\r\n");
        } else {
          data.push(line);
        }
        continue;
      }
      const cmd = line.toUpperCase();
      if (cmd.startsWith("EHLO")) sock.write("250-localhost\r\n250-SIZE 35882577\r\n250 OK\r\n");
      else if (cmd.startsWith("HELO")) sock.write("250 OK\r\n");
      else if (cmd.startsWith("MAIL FROM")) { remitente = line; sock.write("250 OK\r\n"); }
      else if (cmd.startsWith("RCPT TO")) { destinatarios.push(line); sock.write("250 OK\r\n"); }
      else if (cmd.startsWith("DATA")) { enData = true; sock.write("354 go\r\n"); }
      else if (cmd === "QUIT") { sock.write("221 bye\r\n"); sock.end(); }
      else if (cmd === "RSET") sock.write("250 OK\r\n");
      else if (cmd === "NOOP") sock.write("250 OK\r\n");
      else if (cmd.startsWith("STARTTLS")) sock.write("454 no TLS\r\n");
      else sock.write("250 OK\r\n");
    }
  });
}).listen(2525);

process.on("exit", () => {
  // al terminar el proceso padre, escribimos (no aplica)
});

function volcar() {
  if (mensajes.length) {
    fs.appendFileSync(ARCHIVO, JSON.stringify(mensajes, null, 2) + "\n");
    mensajes = [];
  }
}

// Volcado periódico de lo capturado
setInterval(volcar, 500);
console.log("SMTP stub en 2525");
